def _get_display_output(msg, color=None, stderr=False):
    """Generate the display output string based on color and stream settings.

    Args:
        msg: The message to display.
        color: The color to apply if not None.
        stderr: Whether to write to stderr.

    Returns:
        The message string, potentially colorized.
    """
    if color:
        msg = stringc(msg, color)
    return msg

def _print_message(msg, stderr=False):
    """Print a message to the appropriate stream with UTF-8 encoding handling.

    Args:
        msg: The message to print.
        stderr: Whether to write to stderr.
    """
    try:
        print msg
    except UnicodeEncodeError:
        print msg.encode('utf-8')

def _print_message_stderr(msg):
    """Print a message to stderr with UTF-8 encoding handling.

    Args:
        msg: The message to print.
    """
    try:
        print >>sys.stderr, msg
    except UnicodeEncodeError:
        print >>sys.stderr, msg.encode('utf-8')

def display(msg, color=None, stderr=False, screen_only=False, log_only=False, runner=None):
    # prevent a very rare case of interlaced multiprocess I/O
    log_flock(runner)
    msg2 = msg
    if color:
        msg2 = _get_display_output(msg, color)
    if not log_only:
        if not stderr:
            _print_message(msg2)
        else:
            _print_message_stderr(msg2)
    if constants.DEFAULT_LOG_PATH != '':
        while msg.startswith("\n"):
            msg = msg.replace("\n","")
        if not screen_only:
            if color == 'red':
                logger.error(msg)
            else:
                logger.info(msg)
    log_unflock(runner)

def call_callback_module(method_name, *args, **kwargs):

    for callback_plugin in callback_plugins:
        # a plugin that set self.disabled to True will not be called
        # see osx_say.py example for such a plugin
        if getattr(callback_plugin, 'disabled', False):
            continue
        methods = [
            getattr(callback_plugin, method_name, None),
            getattr(callback_plugin, 'on_any', None)
        ]
        for method in methods:
            if method is not None:
                method(*args, **kwargs)

def vv(msg, host=None):
