    public Vector<BuildListener> getBuildListeners() {
        synchronized (listenersLock) {
            Vector<BuildListener> r = new Vector<BuildListener>(listeners.length);
            for (int i = 0; i < listeners.length; i++) {
                r.add(listeners[i]);
            }
            return r;
        }
    }

