     * Set the base directory for the project, checking that
     * the given filename exists and is a directory.
     *
     * @param baseDir The project base directory.
     *                Must not be <code>null</code>.
     *
     * @exception BuildException if the directory if invalid.
     */
    public void setBasedir(String baseDir) throws BuildException {
        setBaseDir(new File(baseDir));
    }

    /**
     * Set the base directory for the project, checking that
     * the given file exists and is a directory.
     *
     * @param baseDir The project base directory.
     *                Must not be <code>null</code>.
     * @exception BuildException if the specified file doesn't exist or
     *                           isn't a directory.
     */
    public void setBaseDir(File baseDir) throws BuildException {
        File normalizedBaseDir = normalizeBaseDir(baseDir);
        if (!normalizedBaseDir.exists()) {
            throw new BuildException("Basedir " + normalizedBaseDir.getAbsolutePath()
                + " does not exist");
        }
        if (!normalizedBaseDir.isDirectory()) {
            throw new BuildException("Basedir " + normalizedBaseDir.getAbsolutePath()
                + " is not a directory");
        }
        this.baseDir = normalizedBaseDir;
        setPropertyInternal(MagicNames.PROJECT_BASEDIR, this.baseDir.getPath());
        log("Project base dir set to: " + this.baseDir, MSG_VERBOSE);
    }

    /**
     * Normalize the provided base directory file.
     *
     * @param baseDir The base directory to normalize.
     *                Must not be <code>null</code>.
     * @return the normalized base directory.
     */
    private File normalizeBaseDir(File baseDir) {
        return FILE_UTILS.normalize(baseDir.getAbsolutePath());
    }

    /**
     * Return the base directory of the project as a file object.
     *
     * @return the project base directory, or <code>null</code> if the
     *         base directory has not been successfully set to a valid value.
     */
    public File getBaseDir() {
        if (baseDir == null) {
            try {
                setBasedir(".");
            } catch (BuildException ex) {
                ex.printStackTrace();
            }
        }
        return baseDir;
    }

    /**
     * Set &quot;keep-going&quot; mode. In this mode Ant will try to execute
     * as many targets as possible. All targets that do not depend
     * on failed target(s) will be executed.  If the keepGoing settor/getter
     * methods are used in conjunction with the <code>ant.executor.class</code>
     * property, they will have no effect.
     * @param keepGoingMode &quot;keep-going&quot; mode
     * @since Ant 1.6
