        BuildListener[] currListeners = listeners;
        for (int i = 0; i < currListeners.length; i++) {
            if (currListeners[i] instanceof SubBuildListener) {
                ((SubBuildListener) currListeners[i]).subBuildStarted(event);
            }
        }
